total = 0
for value in range(6):
    if value % 2:
        total += value
print(total)

def make_adder(amount):
    def add(value):
        return amount + value
    return add
print(make_adder(5)(7))

class Point(object):
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def total(self):
        return self.x + self.y
print(Point(3, 4).total())

